const $=s=>document.querySelector(s),S={lib:null,tables:null,version:'',files:[],assign:new Map(),overrides:new Map(),result:null,meta:null,busy:false,authorized:false,canManage:false,baseRevision:null,editor:null,editorPage:0,canAccept:false,acceptId:null,accepted:false,dashboard:null,dashboardDirty:true};
