async function downloadRuleTemplate(useCurrent=true){const templateSource=useCurrent?S.tables:null;
 const tables=ruleTemplateTables(templateSource),book=XLSX.utils.book_new();
 const guides=[['Mục','Hướng dẫn'],['Nguồn mẫu',templateSource?'Toàn bộ thư viện đang mở, có thể bao gồm thay đổi chưa lưu.':'Mẫu trống, chưa có rule. Điền thông tin trước khi nạp.'],['Phiên bản đối chiếu',S.baseRevision??'Chưa tải Kho dữ liệu'],['Cách dùng','Bổ sung/sửa trong Excel → Thiết lập rule → Nạp file rule → kiểm tra → Lưu rule Kho dữ liệu.'],['Lưu theo Rule ID','File được ghép theo Rule ID: cập nhật các rule trong file, giữ các dự án khác. Trường chuẩn dùng chung theo Template.'],['Bản mới nhất','Nếu muốn bắt đầu từ bản Kho dữ liệu mới nhất: Làm mới rule trong bước Xem rule rồi tải mẫu.'],['Truong_chuan','Một dòng = một trường đầu ra của một Template. Thứ tự là số nguyên dương. Tên cột duy nhất trong Template.'],['Mapping','Một dòng = một nguồn của một trường đầu ra trong Rule ID/dự án. Rule ID phải khớp ở các bảng.'],['Nguon','Một MAIN cho mỗi Rule ID. Khai báo sheet và dòng tiêu đề; LOOKUP cần nguồn đối chiếu và khóa nối.'],['Quy_doi','Tùy chọn. Ví dụ M → Nam. Nếu không dùng, giữ nguyên header và để trống dữ liệu.'],['Dieu_kien','Tùy chọn. Cùng nhóm = AND. SET, CLEAR, ERROR_ROW hoặc SKIP_ROW.'],['Trạng thái','NHAP để xem thử, SAN_SANG khi đã xác nhận, TAT để ngừng dùng. VI_DU không chạy.'],['Bắt buộc','YES hoặc NO. CHUA_XAC_NHAN cần xác nhận trước khi dùng chính thức.'],['Kiểu dữ liệu','TEXT, INTEGER, NUMBER, DATE. Mã nhân viên, điện thoại và tài khoản ngân hàng nên giữ TEXT để không mất số 0 đầu.'],['Cách lấy','COLUMN đọc cột nguồn; LOOKUP tra cứu; FIXED dùng giá trị cố định; PARAM dùng tham số lần chạy.'],['Ưu tiên','Số nguyên từ 1; số nhỏ được xét trước; giá trị không trống đầu tiên được chọn, giữ số 0.'],['Tên cột gợi ý','Phân cách tên tương đương bằng dấu ;.'],['Khóa ghép','Phân cách các cột bằng dấu ;, cùng số lượng và thứ tự giữa hai phía.'],['Thông tin riêng tư','Không đặt API key, mật khẩu hoặc dữ liệu nhân viên vào thư viện rule.']];
 for(const [name,rows] of Object.entries({...tables,Huong_dan:guides})){
  const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=rows[0].map((_,i)=>({wch:name==='Huong_dan'?(i===0?26:105):Math.min(48,Math.max(16,...rows.map(r=>String(r[i]??'').length+2)))}));
  if(name!=='Huong_dan')ws['!autofilter']={ref:XLSX.utils.encode_range({r:0,c:0},{r:Math.max(0,rows.length-1),c:rows[0].length-1})};
  XLSX.utils.book_append_sheet(book,ws,name);
 }
 XLSX.writeFile(book,templateSource?'Staffing_Rule_HienTai_r'+(S.baseRevision??0)+'.xlsx':'Staffing_Rule_MauTrong.xlsx');
 message('Đã tải form Excel. Điền rule dự án, nạp file rồi Lưu rule Kho dữ liệu.');
}
