 const toast=make('aside','<strong>Chưa hoàn tất thao tác</strong><button type="button" id="dismiss-toast" aria-label="Đóng thông báo">×</button><div id="toast-text"></div>','error-toast');toast.id='error-toast';toast.hidden=true;toast.setAttribute('role','alert');document.body.append(toast);
 $('#message').tabIndex=-1;
 const dialog=make('dialog',`<div class="section-title"><h2>Khai báo nguồn MASTER / LOOKUP</h2><button type="button" data-close-master>Đóng</button></div><div class="master-body">
 <p><b>MASTER</b> là bảng danh mục để tra bổ sung thông tin. Chọn file chỉ cung cấp dữ liệu; cấu hình cách nối nằm trong <b>Thiết lập rule → Chỉnh thư viện → Nguon</b>.</p>
 <h3>1. Khai báo nguồn cho đúng Rule ID</h3><div class="scroll"><table><tr><th>Cột trong Nguon</th><th>Ví dụ tra danh mục dự án</th></tr>
 <tr><td>Trạng thái</td><td>SAN_SANG (dùng chính thức)</td></tr><tr><td>Rule ID</td><td>VNM_HR_v1 — phải trùng Rule ID đang chạy</td></tr><tr><td>Nguồn ID</td><td>MASTER_HUBONE — phải trùng nguồn được gọi trong Mapping</td></tr><tr><td>Vai trò / Kênh</td><td>LOOKUP / FILE</td></tr><tr><td>Sheet / bảng</td><td>MASTER HUBONE — tên tab Excel thực tế; có thể để trống và chọn thủ công</td></tr><tr><td>Dòng tiêu đề Excel</td><td>1 nếu tên cột nằm ở dòng 1</td></tr><tr><td>Nguồn nối tới</td><td>PARAM</td></tr><tr><td>Khóa tại nguồn</td><td>Project Code — cột khóa trong sheet MASTER</td></tr><tr><td>Khóa phía đối chiếu</td><td>project_code — tham số Mã dự án ở bước 1</td></tr><tr><td>Trùng khóa</td><td>ERROR — báo lỗi nếu MASTER có nhiều dòng cùng mã</td></tr><tr><td>Không tìm thấy</td><td>ERROR — báo lỗi; hoặc BLANK để để trống</td></tr></table></div>
 <p>Ví dụ: bước 1 có Mã dự án = <b>VNM</b> → tìm dòng MASTER có <b>Project Code = VNM</b>. Tên cột <b>Project Code</b> là ví dụ; thay bằng đúng header trong file MASTER của bạn.</p>
 <h3>2. Nếu tra theo cột trong dữ liệu nhân viên</h3><p>Đặt <b>Nguồn nối tới = VNM_HR_MAIN</b>. <b>Khóa tại nguồn</b> là cột trong MASTER, ví dụ Project Code; <b>Khóa phía đối chiếu</b> là cột chứa cùng mã trong Sheet5, ví dụ MaDuAn. Hai phía so sánh giá trị để tìm dòng. Khóa nhiều cột dùng dấu <b>;</b>, cùng số lượng và thứ tự.</p>
 <h3>3. Khai báo cột cần lấy trong Mapping</h3><p>Ví dụ cột đầu ra Company Name: cùng Rule ID, Nguồn ID = MASTER_HUBONE, Cách lấy = LOOKUP, Cột nguồn = tên cột công ty thực tế trong MASTER, Trạng thái = SAN_SANG. Thêm từng dòng cho các cột cần lấy.</p>
 <p>Bấm <b>Áp dụng bản nháp → Đóng → Lưu rule Kho dữ liệu</b>. Quay lại bước 1 kiểm tra rule, rồi bước 2 chọn Sheet5 cho MAIN và MASTER HUBONE cho LOOKUP. Mỗi Rule ID có một dòng MAIN và một dòng MASTER riêng nếu cần dùng danh mục đó.</p>
 <p>Nếu MASTER chỉ có một dòng mà không có khóa, vẫn cần bổ sung cột khóa thích hợp hoặc đổi các mapping sang FIXED/PARAM theo nghiệp vụ. Tool không tự lấy tùy ý dòng đầu tiên. Nếu không dùng MASTER, chuyển các mapping tham chiếu nguồn này và dòng nguồn sang TAT.</p></div>`,'master-dialog');dialog.id='master-guide';document.body.append(dialog);
 document.querySelectorAll('[data-master-help]').forEach(b=>b.onclick=()=>dialog.showModal());dialog.querySelector('[data-close-master]').onclick=()=>dialog.close();
 $('[data-panel="guide"] section').append(make('p','<button type="button" id="guide-master" class="ghost">Xem hướng dẫn khai báo MASTER</button>'));$('#guide-master').onclick=()=>dialog.showModal();
