 const panel=make('div',`<section id="master-management"><div class="section-title"><h2>Danh mục MASTER dùng chung</h2><button type="button" id="master-reload" class="small ghost">Tải bản đã lưu</button></div><p class="muted">Quản trị nhập một lần, user chọn tên để tự điền mã. Một dòng là một tổ hợp dự án / dịch vụ / công ty / ngành / HO. Một dự án có thể có nhiều dịch vụ và HO.</p><div class="actions"><button type="button" id="master-template">Tải mẫu MASTER</button><label class="upload">Nạp Excel MASTER<input id="master-file" class="file-control" type="file" accept=".xlsx,.xls"></label><button type="button" id="master-add">Thêm dòng</button><button type="button" id="master-save" class="primary">Lưu danh mục MASTER</button></div><div id="master-import-choice" hidden><label>Sheet MASTER<select id="master-sheet"></select></label><button type="button" id="master-import-sheet">Nạp sheet để kiểm tra</button></div><div class="actions master-column-actions"><input id="master-new-column" placeholder="Tên cột bổ sung nếu cần"><button type="button" id="master-add-column" class="small ghost">Thêm cột</button><span id="master-count" class="muted"></span></div><p id="master-status" role="status"></p><div id="master-editor" class="scroll"></div></section>`);panel.dataset.panel='master';panel.hidden=true;$('#workspace').append(panel);
